# ---------------------------------------------------------------------
# config object
# ---------------------------------------------------------------------
class BaseConfig:
    def __init__(self, Polar=np.nan, epsilon_0=np.nan, mu_up=np.nan, mu_down=np.nan):

        self.m_r = 0.5
        self.r = 1.0
        self.m_up = 2 * self.m_r
        self.m_dn = 2 * self.m_r * self.r
        self.M = self.m_up + self.m_dn

        # inputs
        self.Polar = Polar
        self.epsilon_0 = epsilon_0
        self.mu_up = mu_up
        self.mu_down = mu_down

        # total density
        self.ntarget = 1.0

        # MF polarization
        self.Polar_c_mf = self.epsilon_0 * np.sqrt(2 / self.epsilon_0 - 1)

        # density targets
        if np.isfinite(self.Polar):
            self.nuptarget = 0.5 * self.ntarget * (1 + self.Polar)
            self.ndntarget = 0.5 * self.ntarget * (1 - self.Polar)
        else:
            self.nuptarget = 0.5
            self.ndntarget = 0.5

        self.kF_up = np.sqrt(2 * self.nuptarget)
        self.kF_dn = np.sqrt(2 * self.ndntarget)

        # derived placeholders
        self.g = np.nan
        self.h = np.nan
        self.qFFLO = np.nan
        self.k_mu_down = np.nan
        self.k_mu_up = np.nan
        self.k_jump_up = np.nan
        self.k_jump_down = np.nan

        self.update_computed()

    def update_computed(self):
        self.g = 0.5 * np.log(self.epsilon_0 / 2) if self.epsilon_0 > 0 else np.nan

        if (self.mu_up is not None) and (self.mu_down is not None):
            self.h = (self.mu_up - self.mu_down) / 2
            self.qFFLO = np.sqrt(max(self.mu_up, 0)) - np.sqrt(max(self.mu_down, 0))
        else:
            self.h = np.nan
            self.qFFLO = np.nan

        self.k_mu_down = np.sqrt(self.m_dn * self.mu_down) if (self.mu_down is not None and self.mu_down > 0) else 0.0
        self.k_mu_up = np.sqrt(self.m_up * self.mu_up) if (self.mu_up is not None and self.mu_up > 0) else 0.0

    def update(self, **kwargs):
        for k, v in kwargs.items():
            setattr(self, k, v)

        if ("Polar" in kwargs) or ("ntarget" in kwargs):
            P = float(self.Polar) if np.isfinite(self.Polar) else 0.0
            nt = float(self.ntarget)
            self.nuptarget = 0.5 * nt * (1.0 + P)
            self.ndntarget = 0.5 * nt * (1.0 - P)
            self.kF_up = np.sqrt(2 * self.nuptarget)
            self.kF_dn = np.sqrt(2 * self.ndntarget)

        self.update_computed()


