# ---------------------------------------------------------------------
# Gamma and its ingredients
# ---------------------------------------------------------------------
def calculate_z_down(P, w):
    mu_down = configuration.mu_down
    mu_up = configuration.mu_up
    return mu_down - (mu_up / r) - (P ** 2 / m_down) + w


def calculate_z_up(P, w):
    mu_down = configuration.mu_down
    mu_up = configuration.mu_up
    return mu_up - (mu_down / r) - (P ** 2 / m_up) + w


def calculate_A_down(P, w):
    mu_up = configuration.mu_up
    z = calculate_z_down(P, w)
    term1 = z / 2
    term2 = ((P ** 2) / (M * r))
    term3 = np.sign(np.real(z)) * np.sqrt((z / 2) ** 2 - (P ** 2 / (m_down * r)) * mu_up)
    return term1 + term2 + term3


def calculate_A_up(P, w):
    mu_down = configuration.mu_down
    z = calculate_z_up(P, w)
    term1 = z / 2
    term2 = ((P ** 2) / (M * r))
    term3 = np.sign(np.real(z)) * np.sqrt((z / 2) ** 2 - (P ** 2 / (m_up * r)) * mu_down)
    return term1 + term2 + term3


def Gamma(P, w):
    mu_down = configuration.mu_down
    mu_up = configuration.mu_up
    epsilon_0 = configuration.epsilon_0

    term = (P ** 2 / M) - mu_up - mu_down - w
    T2_minus1 = -1 / (8 * np.pi) * np.log(term / (epsilon_0))

    I_F_down = 1 / (8 * np.pi) * (np.log(calculate_A_up(P, w)) - np.log(term) - 1j * np.pi * np.sign(np.imag(w)))
    I_F_up = 1 / (8 * np.pi) * (np.log(calculate_A_down(P, w)) - np.log(term) - 1j * np.pi * np.sign(np.imag(w)))

    if mu_down < 0 and mu_up > 0:
        return 1 / (T2_minus1 - I_F_up)
    elif mu_down >= 0 and mu_up < 0:
        return 1 / (T2_minus1 - I_F_down)
    elif mu_down < 0 and mu_up < 0:
        return 1 / (T2_minus1)
    elif mu_down > 0 and mu_up > 0:
        return 1 / (T2_minus1 - I_F_up - I_F_down)


