def _ensure_targets_from_P(P: float):
    """Set (ν_up^t, ν_dn^t) from ntarget, P if not already present."""
    if hasattr(configuration, "nuptarget") and hasattr(configuration, "ndntarget"):
        return
    nt = float(getattr(configuration, "ntarget", 1.0))
    configuration.update(
        nuptarget=0.5 * nt * (1.0 + float(P)),
        ndntarget=0.5 * nt * (1.0 - float(P)),
    )











